/**
 * Renders a crisp SVG logo for any technology or capability in the stack.
 * All logos are colored with #F7F1E2 by default.
 */
export function SkillLogo({
  name,
  size = 16,
  className = "",
  color = BRAND_COLOR,
}: {
  name: string;
  size?: number;
  className?: string;
  color?: string;
}) {
  const normalized = name.toLowerCase().trim();

  // 1. Direct brand logo matching
  if (normalized.includes("laravel")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.laravel} />
      </svg>
    );
  }

  if (normalized.includes("golang") || normalized.startsWith("go ")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.go} />
      </svg>
    );
  }

  if (normalized.includes("php")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.php} />
      </svg>
    );
  }

  if (normalized.includes("postgres")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.postgresql} />
      </svg>
    );
  }

  if (normalized.includes("mysql") || normalized.includes("mariadb")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.mysql} />
      </svg>
    );
  }

  if (normalized.includes("linux") || normalized.includes("debian") || normalized.includes("ubuntu")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.linux} />
      </svg>
    );
  }

  if (normalized.includes("nginx")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.nginx} />
      </svg>
    );
  }

  if (normalized.includes("docker") || normalized.includes("container")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.docker} />
      </svg>
    );
  }

  if (normalized.includes("git")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.git} />
      </svg>
    );
  }

  if (normalized.includes("bash")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.gnubash} />
      </svg>
    );
  }

  if (normalized.includes("vue")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.vuedotjs} />
      </svg>
    );
  }

  if (normalized.includes("typescript")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.typescript} />
      </svg>
    );
  }

  if (normalized.includes("javascript")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.javascript} />
      </svg>
    );
  }

  if (normalized.includes("tailwind")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.tailwindcss} />
      </svg>
    );
  }

  if (normalized.includes("alpine")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.alpinedotjs} />
      </svg>
    );
  }

  if (normalized.includes("vite")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.vite} />
      </svg>
    );
  }

  if (normalized.includes("html") || normalized.includes("css")) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        className={className}
      >
        <path fill={color} d={BRAND_PATHS.html5} />
      </svg>
    );
  }

  // 2. Architectural & Engineering Capabilities
  if (normalized.includes("api") || normalized.includes("restful")) {
    return <Network size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  if (normalized.includes("auth") || normalized.includes("rbac")) {
    return <ShieldCheck size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  if (normalized.includes("queue") || normalized.includes("job")) {
    return <Layers size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  if (normalized.includes("schema") || normalized.includes("relation")) {
    return <Table2 size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  if (normalized.includes("eloquent") || normalized.includes("orm") || normalized.includes("gorm")) {
    return <Binary size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  if (normalized.includes("query") || normalized.includes("optimization") || normalized.includes("index")) {
    return <Zap size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  if (normalized.includes("reconciliation") || normalized.includes("ledger") || normalized.includes("financial")) {
    return <Scale size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  if (normalized.includes("integrity") || normalized.includes("normalization")) {
    return <ShieldCheck size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  if (normalized.includes("audit") || normalized.includes("logging") || normalized.includes("verification")) {
    return <FileCheck2 size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  if (normalized.includes("ssl") || normalized.includes("tls") || normalized.includes("domain")) {
    return <Lock size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  if (normalized.includes("ssh") || normalized.includes("security")) {
    return <Terminal size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }

  // Fallback
  return <Code2 size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
}

/**
 * Category header SVG icons for the 4 primary stacks/disciplines, colored with #F7F1E2
 */
export function CategoryStackIcon({
  id,
  size = 20,
  className = "",
  color = BRAND_COLOR,
}: {
  id: string;
  size?: number;
  className?: string;
  color?: string;
}) {
  switch (id) {
    case "backend":
      return <Server size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
    case "database":
      return <Database size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
    case "infrastructure":
      return <Globe size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
    case "frontend":
      return <Monitor size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
    default:
      return <Terminal size={size} color={color} strokeWidth={1.8} className={className} aria-hidden="true" />;
  }
}
